// global variables
const float PI = 3.14159265;


// returns polar coordinates rf of a point with cartesian coordinates uv
vec2 toLogPolar(vec2 uv){

    return vec2(exp(length(uv)*2.),atan(uv.y,uv.x));
}


// rotation matrix 
mat2 rotM(float f){

    return mat2(cos(f),sin(f),-sin(f),cos(f));
}


// shear matrix
mat2 shearM(float f){

    return mat2(1.,0.,f,1.);
}


//zigZag patern
float zigZag(vec2 uv, float a, float b, float c, float d){

    return min(min(fract(a*uv.x),1.-fract(b*uv.x)),min(fract(c*uv.y),1.-fract(d*uv.y)));
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // normalize pixel coordinates 
    vec2 uv = (fragCoord-.5*iResolution.xy)/iResolution.y;

    // cliped time
    float t = clamp(0.0,21.,iTime);

    vec2 rf = toLogPolar(rotM(0.1*t)*uv/(0.2*t+0.6));
    rf.y = rf.y/PI;

    float zZ = zigZag(rf, 3., 3., 3., 3.);

    // Output to screen
    fragColor = vec4(zZ);
}
